mapper.select:
SELECT SUM(TDY_INTINCEXP) FROM ( SELECT TDY_INTINCEXP FROM PTL_SEC_VALUTION
CDATE = STR_TO_DATE(#{carryDate},'%Y-%m-%d') AND Inv_Aim = '999999'
and portfolio_id = #{portfolioId}
and finprod_id = #{finprodId}
and sec_acct_id = #{secAcctId}
UNION ALL
SELECT SUM(SHARE_AMT*-1) TDY_INTINCEXP FROM TRD_FIN_PRODUCT_DEAL_TOTAL WHERE PS='T12' AND FINPROD_ID=#{finprodId} AND TRADE_STATUS='01' AND IS_CANCEL='N' AND SETTLE_DATE=STR_TO_DATE(#{tradeDate},'%Y-%m-%d')
and CHL_ID = #{secAcctId}
and CHL_ID IS NULL
)

SELECT IFNULL(T1.ENTRUST_AMT,'-1') entrustAmt, IFNULL(T1.ENTRUST_NUM,0) entrustNum, IFNULL(T2.FINISH_AMT,0) finishAmt, IFNULL(T5.PRIN_AMT,0) prinAmt FROM ETR_ENTRUST T1 LEFT JOIN ( SELECT FINISH_AMT, ENTRUST_ID FROM ETR_FINISH_STATUS
ENTRUST_ID = #{entrustId}
) T2 ON T1.ENTRUST_ID = T2.ENTRUST_ID LEFT JOIN ( SELECT T4.PRIN_AMT,T3.ENTRUST_ID FROM WFL_TRD_PRODUCT_DEAL_ADD T3 LEFT JOIN WFL_TRD_PRODUCT_DEAL T4 ON T3.TRADE_ID = T4.TRADE_ID
T3.ENTRUST_ID = #{entrustId} AND T4.PS IN (#{pssg},#{pssh})
AND T4.TRADE_ID <> #{tradeId}
) T5 ON T1.ENTRUST_ID = T5.ENTRUST_ID
T1.ENTRUST_ID = #{entrustId}
